script.body:
var examType = org.unitime.timetable.model.ExamType.findByReference(type);
var exams = new java.util.TreeSet(org.unitime.timetable.model.Exam.findAll(new java.lang.Long(session.getUniqueId()), examType));

log.setStatus('Updading ' + exams.size() + ' exams ...', exams.size());

for (var i = exams.iterator(); i.hasNext(); ) {
	var exam = i.next();
	log.incProgress();
	if (!override && !exam.getInstructors().isEmpty()) continue;
	log.info('Updating ' + exam.getLabel());

	for (var j = exam.getInstructors().iterator(); j.hasNext();) {
		var instructor = j.next();
		instructor.getExams().remove(exam);
		j.remove();
	}

    for (var j = exam.getOwners().iterator(); j.hasNext(); ) {
		var owner = j.next();
		log.info('  owner ' + owner.getLabel());
		var object = owner.getOwnerObject();
		if (object instanceof org.unitime.timetable.model.Class_) {
			for (var k = object.getClassInstructors().iterator(); k.hasNext(); ) {
				var instructor = k.next();
				if (instructor.getPercentShare() >= 100)
					exam.getInstructors().add(instructor.getInstructor());
			}
		} else if (object instanceof org.unitime.timetable.model.InstrOfferingConfig && !classOnly) {
			var top = null;
			for (var k = object.getSchedulingSubparts().iterator(); k.hasNext(); ) {
				var s = k.next();
				if (s.getParentSubpart() == null && (top == null ||
						s.getItype().compareTo(top.getItype()) < 0 ||
						(s.getItype().compareTo(top.getItype()) == 0 && s.getClasses().size() < top.getClasses().size())))
					top = s;
			}
			if (top != null) {
				var classes = new java.util.ArrayList(top.getClasses());
				for (var c = 0; c < classes.size(); c++) {
					var clazz = classes.get(c);
					log.info("   using " + clazz);
					for (var k = clazz.getClassInstructors().iterator(); k.hasNext(); ) {
						var instructor = k.next();
						if (instructor.getPercentShare() >= 100)
							exam.getInstructors().add(instructor.getInstructor());
					}
				}
			}
		} else if (!classOnly) {
			for (var k = owner.getCourse().getInstructionalOffering().getInstrOfferingConfigs().iterator(); k.hasNext(); ) {
				var config = k.next();
				var top = null;
				for (var l = config.getSchedulingSubparts().iterator(); l.hasNext(); ) {
					var s = l.next();
					if (s.getParentSubpart() == null && (top == null ||
							s.getItype().compareTo(top.getItype()) < 0 ||
							(s.getItype().compareTo(top.getItype()) == 0 && s.getClasses().size() < top.getClasses().size())))
						top = s;
				}
				if (top != null) {
					var classes = new java.util.ArrayList(top.getClasses());
					for (var c = 0; c < classes.size(); c++) {
						var clazz = classes.get(c);
						log.info("   using " + clazz);
						for (var k = clazz.getClassInstructors().iterator(); k.hasNext(); ) {
							var instructor = k.next();
							if (instructor.getPercentShare() >= 100)
								exam.getInstructors().add(instructor.getInstructor());
						}
					}
				}
			}
		}
	}

	if (exam.getInstructors().isEmpty())
		log.info("    no instructors");
	else
		log.info("    instructors " + new java.util.TreeSet(exam.getInstructors()));

	for (var j = exam.getInstructors().iterator(); j.hasNext();) {
		var instructor = j.next();
		instructor.getExams().add(exam);
		hibSession.saveOrUpdate(instructor);
	}

	hibSession.saveOrUpdate(exam);
}
